// Verify HMAC signature from Perfex CRM.
// Requires on self-hosted n8n: NODE_FUNCTION_ALLOW_BUILTIN=crypto
// Requires on the Webhook node: Options -> Raw Body = ON
//
// v3 changes over v2 (2026-08-24):
//   The 300-second freshness window silently killed the sender's own retry
//   queue. N8n_sender.php re-signs the STORED body on every retry, so the
//   timestamp inside it never moves, and the ladder runs 5m / 15m / 1h / 4h /
//   12h. Every one of those retries arrived older than 300s and was rejected.
//   The window now covers the whole ladder, and replay protection is done the
//   only way that actually distinguishes a replay from a retry: remembering
//   which signed bodies were already accepted.
const crypto = require('crypto');

// The sender's final retry fires at 12h (BACKOFF_INTERVALS in N8n_sender.php).
// 13h leaves an hour of margin for a queue that drains slowly.
const MAX_AGE_SEC = 13 * 60 * 60;
// Tolerated clock difference when the sender's clock runs ahead of ours.
const CLOCK_SKEW_SEC = 300;

const secret = $env.PERFEX_HMAC_SECRET;
if (!secret) {
  return [{ json: { verified: false, error: 'PERFEX_HMAC_SECRET is not set' } }];
}

// items[0] is this node's own input item. The Webhook node puts the request in
// json as { body, headers, params, query } - headers are NOT on the item itself.
const item = items[0];
const req = item.json || {};
const headers = req.headers || {};

const sig = headers['x-perfex-signature'];
if (!sig) {
  return [{ json: { verified: false, error: 'missing X-Perfex-Signature header' } }];
}

// The sender signs the exact JSON bytes it wrote, so we must hash those bytes,
// not a re-serialised object. With Raw Body on they arrive as binary.
let raw = null;
if (item.binary && item.binary.data) {
  const bin = await getBinaryDataAsync(item);
  const b64 = (bin && bin.data && bin.data.data) || item.binary.data.data;
  raw = Buffer.from(b64, 'base64');
} else if (typeof req.body === 'string') {
  raw = Buffer.from(req.body, 'utf8');
}
if (!raw) {
  return [{ json: { verified: false, error: 'raw body not available - enable Raw Body on the Webhook node' } }];
}

const expected = crypto.createHmac('sha256', secret).update(raw).digest('hex');
const a = Buffer.from(expected, 'hex');
const b = Buffer.from(String(sig).trim(), 'hex');
if (a.length !== b.length || !crypto.timingSafeEqual(a, b)) {
  return [{ json: { verified: false, error: 'bad signature' } }];
}

// Only now is anything in the body trustworthy - including its timestamp.
let payload;
try {
  payload = JSON.parse(raw.toString('utf8'));
} catch (e) {
  return [{ json: { verified: false, error: 'signed body is not valid JSON' } }];
}

// Use the timestamp from the SIGNED body. X-Perfex-Timestamp is a separate
// header, outside the signature, and freely settable by whoever sends.
const t = Number(payload.timestamp);
if (!Number.isFinite(t)) {
  return [{ json: { verified: false, error: 'missing or malformed timestamp in signed body' } }];
}
const ageSec = Date.now() / 1000 - t;
if (ageSec < -CLOCK_SKEW_SEC) {
  return [{ json: { verified: false, error: 'timestamp is in the future' } }];
}
if (ageSec > MAX_AGE_SEC) {
  return [{ json: { verified: false, error: 'timestamp older than the retry window' } }];
}

// Replay protection. A wide window is required for retries to work at all, so
// freshness alone cannot carry it. The signature is a deterministic hash of the
// signed bytes, which makes it a usable idempotency key with no cooperation
// needed from the sender - the payload carries no event id of its own.
//
// Honest limit: workflow static data is written when the execution finishes and
// is not transactional, so two deliveries racing inside one execution window can
// both pass. It stops the ordinary replay, not a determined attacker with
// concurrent access. A shared store (Redis SETNX) is the real answer and needs a
// node this blueprint does not ship.
const store = $getWorkflowStaticData('global');
if (!store.seenSignatures) {
  store.seenSignatures = {};
}
const nowSec = Math.floor(Date.now() / 1000);
for (const key of Object.keys(store.seenSignatures)) {
  if (nowSec - store.seenSignatures[key] > MAX_AGE_SEC) {
    delete store.seenSignatures[key];
  }
}

const already = store.seenSignatures[expected] !== undefined;
store.seenSignatures[expected] = nowSec;

// A duplicate is reported as verified so the workflow answers 200 and the sender
// stops retrying. Downstream must check `duplicate` before writing anything - it
// is the flag that keeps a retried invoice from being booked twice.
return [{
  json: {
    verified: true,
    duplicate: already,
    event: payload.event,
    timestamp: t,
    ageSeconds: Math.round(ageSec),
    data: payload.data,
  },
}];

// Process Invoice Events
const data = $input.first().json.data;
const invoice = data.invoice;
const client = data.client;

return [{
  json: {
    event_type: $input.first().json.event,
    invoice_id: invoice.id,
    invoice_number: invoice.prefix + invoice.number,
    total: invoice.total,
    status: invoice.status,
    client_name: client?.company || 'Unknown',
    client_email: client?.email || '',
    due_date: invoice.duedate,
    public_link: invoice.public_link
  }
}];

// Process Lead Events
const data = $input.first().json.data;
const lead = data.lead;
const status = data.status;
const source = data.source;
const assignedStaff = data.assigned_staff;

return [{
  json: {
    event_type: $input.first().json.event,
    lead_id: lead.id,
    name: lead.name,
    email: lead.email,
    phone: lead.phonenumber,
    company: lead.company,
    status_id: status.id,
    status_name: status.name,
    source_name: source.name,
    assigned_to: assignedStaff?.full_name || 'Unassigned',
    description: lead.description
  }
}];

// Process Task Events
const data = $input.first().json.data;
const task = data.task;
const assignees = data.assignees || [];

const statusLabels = {
  1: 'Not Started',
  2: 'In Progress',
  3: 'Testing',
  4: 'Awaiting Feedback',
  5: 'Complete'
};

return [{
  json: {
    event_type: $input.first().json.event,
    task_id: task.id,
    name: task.name,
    description: task.description,
    status: statusLabels[task.status] || 'Unknown',
    priority: task.priority,
    due_date: task.duedate,
    assignees: assignees.map(a => a.full_name).join(', '),
    admin_link: task.admin_link
  }
}];
